def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        # Check if field starts with quote
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end without closing quote
                return None

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                return None

            fields.append(field)

            # Skip comma if present
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Skip comma if present
            if i < n and line[i] == ',':
                i += 1

    return fields

